from PIL import Image

def prof(path, x0=305, x1=335):
    im = Image.open(path)
    out = []
    for y in range(185, 245):
        s = 0
        n = 0
        for x in range(x0, x1):
            r,g,b = im.getpixel((x,y))
            s += (r+g+b)/3
            n += 1
        out.append((y, s/n))
    return out

def peaks(p, thr_prom=2):
    # local maxima
    ys = []
    for i in range(1, len(p)-1):
        if p[i][1] > p[i-1][1] and p[i][1] >= p[i+1][1] and p[i][1] > 165:
            ys.append(p[i])
    return ys

for path, name in [("side_008","U"), ("side_009","L"), ("side_007","C")]:
    p = prof(f"/home/robot/captures/{path}.jpg")
    pk = peaks(p)
    print(name, "peaks", [(y, round(v,1)) for y,v in pk])
    if len(pk) >= 2:
        dys = [pk[i+1][0]-pk[i][0] for i in range(len(pk)-1)]
        print("  spacing", dys, "mean", sum(dys)/len(dys))
PY"}

